import itertools

def max_independent_set_size(edges, n=9):
    # Brute force for small n
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = adj[v][u] = True

    max_size = 0
    for r in range(n, 0, -1):
        for combo in itertools.combinations(range(n), r):
            ok = True
            for i in range(len(combo)):
                for j in range(i+1, len(combo)):
                    if adj[combo[i]][combo[j]]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return r
    return 0

def is_connected(edges, n=9):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False]*n
    stack = [0]
    visited[0] = True
    while stack:
        v = stack.pop()
        for u in adj[v]:
            if not visited[u]:
                visited[u] = True
                stack.append(u)
    return all(visited)

